import AutoFillContract
import AutoFillData
import BitwardenSDKAdapter
import Foundation
import Testing

/// Fixed historical wire shapes, not snapshots generated by the same encoder being tested.
/// All values are synthetic. Previous origin-less caches remain inspectable but unauthorized.
@Suite
struct CacheGoldenCompatibilityTests {
    private let owner = AutoFillAccountIdentity(
        userID: "fixture-user",
        serverBaseURL: URL(string: "https://vault.example.com/base/")!
    )
    private func fixture(_ name: String) throws -> Data {
        let url = try #require(Bundle.module.url(forResource: name, withExtension: "json"))
        return try Data(contentsOf: url)
    }

    @Test
    func originlessGoldenIsDecodableButCannotAcquireAccountAuthority() throws {
        let data = try fixture("cache-originless")
        let decoded = try JSONDecoder().decode(SharedVaultCacheData.self, from: data)
        #expect(decoded.ciphers.first?.login?.password == "fixture-encrypted-password")
        #expect(decoded.owner == nil && decoded.revision == nil && decoded.projectionRevision == nil)
        #expect(throws: SharedVaultCacheError.wrongAccount) { _ = try LegacyAutoFillCacheCodec(owner: owner).decode(data) }
    }

    @Test
    func previousOwnedGoldenPreservesExactServerIdentityWithoutInventingAnOrderFence() throws {
        let data = try fixture("cache-owned-previous")
        let cache = try JSONDecoder().decode(SharedVaultCacheData.self, from: data)
        try cache.validate(for: owner)
        #expect(cache.owner?.serverBaseURL.absoluteString == "https://vault.example.com/base/")
        #expect(cache.projectionRevision == nil)
        let envelope = try LegacyAutoFillCacheCodec(owner: owner).decode(data)
        #expect(envelope.revision == 0)
        #expect(envelope.encryptedOrganizationKeys == ["org-1": "fixture-encrypted-org-key"])
        let normalized = AutoFillAccountIdentity(
            userID: owner.userID,
            serverBaseURL: URL(string: "https://vault.example.com/base")!
        )
        #expect(throws: SharedVaultCacheError.wrongAccount) { try cache.validate(for: normalized) }
    }

    @Test
    func currentGoldenRetainsTheUnsupportedWriteFenceAcrossBothCodecs() throws {
        let codec = LegacyAutoFillCacheCodec(owner: owner)
        let envelope = try codec.decode(fixture("cache-owned-current"))
        #expect(envelope.revision == 17)
        let payload = try #require(envelope.encryptedLoginRecords.first?.encryptedCipherPayload)
        let cipher = try JSONDecoder().decode(CipherResponseDTO.self, from: payload)
        #expect(cipher.hasUnrecognizedPayload && cipher.edit == false)
        #expect(cipher.login?.password == "fixture-encrypted-password")
        let roundTrip = try JSONDecoder().decode(SharedVaultCacheData.self, from: codec.encode(envelope))
        #expect(roundTrip.ciphers.first?.hasUnrecognizedPayload == true)
        #expect(roundTrip.ciphers.first?.edit == false)
    }

    @Test
    func truncatedGoldenCannotBecomeAnEmptySuccessfulCache() throws {
        let bytes = try fixture("cache-owned-current")
        #expect(throws: (any Error).self) {
            _ = try LegacyAutoFillCacheCodec(owner: owner).decode(Data(bytes.prefix(bytes.count / 2)))
        }
    }
}
